"""Change a dictionary of kmer counts to a dictinary with kmer counts
    for a smaller value of k.

    Args:
        D (dict): kmer count dictonary
        general_patttern (str): the general pattern
        length (int): The new value of k

    Returns:
        tuple with downsized dictionary and downsized general pattern
    """
def downsize_contextD(D: Any, general_pattern: Any, length: Any) -> object {
    res = {};
    start = None;
    end = None;
    for context in D {
        if (start is None) {
            assert not (length is None);
            assert (len(context) > length) , f'k-mer:{context} cannot be reduced to length {length}';
            radius1 = len(context) // 2;
            radius2 = length // 2;
            start = radius1 - radius2;
            end = (radius1 - radius2) + length;
        }
        counts = D[context];
        context = context[start:end];
        if (context not in res) {
            res[context] = [0] * len(counts);
        }
        for i in range(len(counts)) {
            res[context][i] += counts[i];
        }
    }
    return (res, general_pattern[start:end]);
}

"""
    Gets the average score for models cross validated using the cross_validate function.
    :param tscores: List. The scores to be averaged. Should be the result of a cross validation using the cross_validate function.
    """
def get_average_score(tscores: Any) -> object {
    score = 0;
    for i in range(0, len(tscores)) {
        score += tscores[(i - 1)];
    }
    score = score / len(tscores);
    return score;
}

"""
    Check buildings of unique height in each row.

    Return True if buildings in a row have unique length, False otherwise.

    >>> check_uniqueness_in_rows(['***21**', '412453*', '423145*', '*543215', '*35214*', '*41532*', '*2*1***'])
    True
    >>> check_uniqueness_in_rows(['***21**', '452453*', '423145*', '*543215', '*35214*', '*41532*', '*2*1***'])
    False
    >>> check_uniqueness_in_rows(['***21**', '412453*', '423145*', '*553215', '*35214*', '*41532*', '*2*1***'])
    False
    """
def check_uniqueness_in_rows(board: list) -> object {
    new_board = board[1:6];
    new_lst = [];
    for els in new_board {
        new_lst += [els[1:6]];
    }
    for elo in new_lst {
        for i in range(5) {
            if (elo.count(elo[i]) > 1) {
                return False;
            }
        }
    }
    return True;
}

"""
    Helper function for regex manipulation:
    Construct a regex representing "any of" the given possibilities
    :param possibilities: list of strings representing different word possibilities
    :param to_add: string to add at the beginning of each possibility (optional)
    :return: string corresponding to regex which represents any of the given possibilities
    """
def any_of(possibilities: Any, to_add: Any = '') -> object {
    assert (len(possibilities) > 0);
    s = '(?:';
    if (len(to_add) > 0) {
        s += possibilities[0] + to_add + ' ';
    } else {
        s += possibilities[0];
    }
    for i in range((len(possibilities) - 1)) {
        if (len(to_add) > 0) {
            s += '|' + possibilities[(i + 1)] + to_add + ' ';
        } else {
            s += '|' + possibilities[(i + 1)];
        }
    }
    return (s + ')');
}

