"""Returns the line and column of the given position in the string.

    Column is 1-based, that means, that the first character in a line has column
    equal to 1. A line with n character also has a n+1 column, which sits just
    before the newline.

    Args:
      data: the original string.
      line: the line at which the string starts.
      column: the column at which the string starts.
      position: the position within the string. It is 0-based.

    Returns:
      A tuple (line, column) with the offset of the position.
    """
def get_line_column(data: Any, line: Any, column: Any, position: Any) -> object {
    data = data[:position];
    toks = data.splitlines();
    if (not toks or (data[-1] in '\n\r')) {
        toks.append('');
    }
    if (len(toks) > 1) {
        return (((line + len(toks)) - 1), (1 + len(toks[-1])));
    } else {
        return (line, (column + position));
    }
}

"""
    fix template expansion after hook copy
    :param content: the duplicated hook content
    :param replacements: array of dictionaries
                         cookiecutter_key => template key expanded
    """
def fix_template_expansion(content: Any, replacements: Any) -> object {
    for replacement in replacements {
        for (key, to_be_replaced) in replacement.items() {
            replacement = (
                chr(123) + chr(123) + 'cookiecutter.' + key + chr(125) + chr(125)
            );
            content = content.replace(to_be_replaced, replacement);
        }
    }
    return content;
}

"""
    Convert a string (e.g. "5M") to number of bytes (int)
    """
def strformat_to_bytes(strformat: Any) -> object {
    suffixes = {'B': 1};
    suffixes['K'] = 1000 * suffixes['B'];
    suffixes['M'] = 1000 * suffixes['K'];
    suffixes['G'] = 1000 * suffixes['M'];
    suffixes['T'] = 1000 * suffixes['G'];
    suffix = strformat[-1];
    amount = int(strformat[:-1]);
    return (amount * suffixes[suffix]);
}

